(function(){if(document.getElementById("faqAccordion")){var s=document.documentElement.getAttribute("lang")||"es-AR",a={"es-AR":"es",en:"en",fr:"fr",pt:"pt"}[s]||"es",t={es:{"@context":"https://schema.org","@type":"FAQPage","@id":"https://www.kinesica.com.ar/#faq",inLanguage:"es-AR",mainEntityOfPage:"https://www.kinesica.com.ar/",mainEntity:[{"@type":"Question",name:"\xBFCu\xE1l es la duraci\xF3n del tratamiento?",acceptedAnswer:{"@type":"Answer",text:"Depender\xE1 del objetivo, la situaci\xF3n del paciente y la evoluci\xF3n del tratamiento."}},{"@type":"Question",name:"\xBFCu\xE1nto dura la sesi\xF3n?",acceptedAnswer:{"@type":"Answer",text:"El tiempo de duraci\xF3n de una sesi\xF3n es variable seg\xFAn el caso y la metodolog\xEDa que se necesite. Tomamos como un tiempo est\xE1ndar 1 hora por sesi\xF3n."}},{"@type":"Question",name:"\xBFFrecuencia de las sesiones?",acceptedAnswer:{"@type":"Answer",text:"Var\xEDa seg\xFAn los casos y los m\xE9todos a emplear. En algunas modalidades las sesiones son semanales y en otras pueden espaciarse cada 2 o 3 semanas."}},{"@type":"Question",name:"\xBFQu\xE9 necesito llevar a la primera sesi\xF3n?",acceptedAnswer:{"@type":"Answer",text:"Tus inquietudes y estudios complementarios si los tuvieses; ropa c\xF3moda. Si sos menor, ven\xED acompa\xF1ado/a por un mayor."}},{"@type":"Question",name:"\xBFEs importante llegar a horario?",acceptedAnswer:{"@type":"Answer",text:"Pedimos puntualidad estricta. Como no contamos con secretaria, llegar a horario evita esperas en la entrada y permite que te atiendan sin demoras."}},{"@type":"Question",name:"\xBFAtienden a trav\xE9s de Prepagas u Obras Sociales?",acceptedAnswer:{"@type":"Answer",text:"Pod\xE9s solicitar reintegros a tu obra social o prepaga."}},{"@type":"Question",name:"\xBFCu\xE1les son los honorarios?",acceptedAnswer:{"@type":"Answer",text:"En el proceso de agendar se informan los valores de las diferentes t\xE9cnicas."}},{"@type":"Question",name:"\xBFD\xF3nde puedo consultar mis turnos?",acceptedAnswer:{"@type":"Answer",text:"Pod\xE9s hacerlo por WhatsApp escribi\xE9ndonos, o en la web de autogesti\xF3n con el apellido, el email de la reserva y el c\xF3digo de gesti\xF3n del mail de confirmaci\xF3n."}},{"@type":"Question",name:"\xBFA qui\xE9nes sirven estos tratamientos?",acceptedAnswer:{"@type":"Answer",text:"A personas con dolores, alteraciones de la sensibilidad, mareos, cambios posturales, lesiones traum\xE1ticas o deportivas, entre otros."}}]},en:{"@context":"https://schema.org","@type":"FAQPage","@id":"https://www.kinesica.com.ar/en/#faq",inLanguage:"en",mainEntityOfPage:"https://www.kinesica.com.ar/en/",mainEntity:[{"@type":"Question",name:"What is the duration of the treatment?",acceptedAnswer:{"@type":"Answer",text:"It depends on the objective, the patient's condition, and the evolution of the treatment."}},{"@type":"Question",name:"How long does a session last?",acceptedAnswer:{"@type":"Answer",text:"The duration of a session varies depending on the case and the methodology required. As a standard time, we consider 1 hour per session."}},{"@type":"Question",name:"How often are sessions scheduled?",acceptedAnswer:{"@type":"Answer",text:"It varies by case and methods. Some modalities are weekly; others may be spaced every 2 or 3 weeks."}},{"@type":"Question",name:"What should I bring to the first session?",acceptedAnswer:{"@type":"Answer",text:"Your questions and any complementary studies; comfortable clothing. Minors should come with an adult."}},{"@type":"Question",name:"Is it important to arrive on time?",acceptedAnswer:{"@type":"Answer",text:"We ask for strict punctuality. As we do not have a receptionist, arriving on time avoids waiting at the entrance and lets us see you without delay."}},{"@type":"Question",name:"Do you accept prepaid health plans or insurance?",acceptedAnswer:{"@type":"Answer",text:"You can request reimbursements from your health insurance provider."}},{"@type":"Question",name:"What are the fees?",acceptedAnswer:{"@type":"Answer",text:"During the booking process, the fees for the different techniques are provided."}},{"@type":"Question",name:"Where can I check my appointments?",acceptedAnswer:{"@type":"Answer",text:"You can check via WhatsApp by messaging us, or on the self-service page with the last name, booking email, and management code from the confirmation email."}},{"@type":"Question",name:"Who can benefit from these treatments?",acceptedAnswer:{"@type":"Answer",text:"People with pain, sensitivity disorders, dizziness, posture issues, traumatic or sports injuries, among others."}}]},fr:{"@context":"https://schema.org","@type":"FAQPage","@id":"https://www.kinesica.com.ar/fr/#faq",inLanguage:"fr",mainEntityOfPage:"https://www.kinesica.com.ar/fr/",mainEntity:[{"@type":"Question",name:"Quelle est la dur\xE9e du traitement ?",acceptedAnswer:{"@type":"Answer",text:"Cela d\xE9pend de l'objectif, de l'\xE9tat du patient et de l'\xE9volution du traitement."}},{"@type":"Question",name:"Combien de temps dure une s\xE9ance ?",acceptedAnswer:{"@type":"Answer",text:"La dur\xE9e varie selon le cas et la m\xE9thode utilis\xE9e. En r\xE8gle g\xE9n\xE9rale, nous pr\xE9voyons environ une heure par s\xE9ance."}},{"@type":"Question",name:"\xC0 quelle fr\xE9quence ont lieu les s\xE9ances ?",acceptedAnswer:{"@type":"Answer",text:"Cela varie selon le cas et les m\xE9thodes. Certaines modalit\xE9s sont hebdomadaires ; d'autres, espac\xE9es de 2 ou 3 semaines."}},{"@type":"Question",name:"Que dois-je apporter \xE0 la premi\xE8re s\xE9ance ?",acceptedAnswer:{"@type":"Answer",text:"Vos questions et examens compl\xE9mentaires si vous en avez ; tenue confortable. Les mineurs doivent \xEAtre accompagn\xE9s d'un adulte."}},{"@type":"Question",name:"Est-il important d'arriver \xE0 l'heure ?",acceptedAnswer:{"@type":"Answer",text:"Nous demandons une ponctualit\xE9 stricte. Sans secr\xE9taire \xE0 l'accueil, arriver \xE0 l'heure \xE9vite d'attendre \xE0 l'entr\xE9e et permet de vous recevoir sans retard."}},{"@type":"Question",name:"Acceptez-vous les mutuelles ou assurances ?",acceptedAnswer:{"@type":"Answer",text:"Vous pouvez demander un remboursement aupr\xE8s de votre assurance ou mutuelle."}},{"@type":"Question",name:"Quels sont les honoraires ?",acceptedAnswer:{"@type":"Answer",text:"Lors de la prise de rendez-vous, les tarifs des diff\xE9rentes techniques sont indiqu\xE9s."}},{"@type":"Question",name:"O\xF9 puis-je consulter mes rendez-vous ?",acceptedAnswer:{"@type":"Answer",text:"Vous pouvez le faire sur WhatsApp en nous \xE9crivant, ou sur la page en libre-service avec le nom, l'e-mail de r\xE9servation et le code de gestion du mail de confirmation."}},{"@type":"Question",name:"Qui peut b\xE9n\xE9ficier de ces traitements ?",acceptedAnswer:{"@type":"Answer",text:"Les personnes souffrant de douleur, troubles de sensibilit\xE9, vertiges, troubles posturaux, blessures traumatiques ou sportives, entre autres."}}]},pt:{"@context":"https://schema.org","@type":"FAQPage","@id":"https://www.kinesica.com.ar/pt/#faq",inLanguage:"pt",mainEntityOfPage:"https://www.kinesica.com.ar/pt/",mainEntity:[{"@type":"Question",name:"Qual \xE9 a dura\xE7\xE3o do tratamento?",acceptedAnswer:{"@type":"Answer",text:"Depende do objetivo, da condi\xE7\xE3o do paciente e da evolu\xE7\xE3o do tratamento."}},{"@type":"Question",name:"Quanto tempo dura cada sess\xE3o?",acceptedAnswer:{"@type":"Answer",text:"A dura\xE7\xE3o varia conforme o caso e a metodologia. Como refer\xEAncia, reservamos cerca de 1 hora por sess\xE3o."}},{"@type":"Question",name:"Com que frequ\xEAncia s\xE3o as sess\xF5es?",acceptedAnswer:{"@type":"Answer",text:"Varia conforme o caso e os m\xE9todos. Algumas modalidades s\xE3o semanais; outras, a cada 2 ou 3 semanas."}},{"@type":"Question",name:"O que devo levar na primeira sess\xE3o?",acceptedAnswer:{"@type":"Answer",text:"Suas d\xFAvidas e exames complementares, se tiver; roupa confort\xE1vel. Menores devem vir acompanhados de um adulto."}},{"@type":"Question",name:"\xC9 importante chegar no hor\xE1rio?",acceptedAnswer:{"@type":"Answer",text:"Pedimos pontualidade rigorosa. Como n\xE3o temos secret\xE1ria, chegar no hor\xE1rio evita esperas na entrada e permite o atendimento sem atrasos."}},{"@type":"Question",name:"Voc\xEAs aceitam planos de sa\xFAde ou reembolso?",acceptedAnswer:{"@type":"Answer",text:"Voc\xEA pode solicitar reembolso junto ao seu plano ou seguro de sa\xFAde."}},{"@type":"Question",name:"Quais s\xE3o os honor\xE1rios?",acceptedAnswer:{"@type":"Answer",text:"No processo de agendamento s\xE3o informados os valores das diferentes t\xE9cnicas."}},{"@type":"Question",name:"Onde posso consultar meus hor\xE1rios?",acceptedAnswer:{"@type":"Answer",text:"Voc\xEA pode consultar pelo WhatsApp escrevendo para n\xF3s, ou na p\xE1gina de autogest\xE3o com o sobrenome, o e-mail da reserva e o c\xF3digo de gest\xE3o do e-mail de confirma\xE7\xE3o."}},{"@type":"Question",name:"Quem pode se beneficiar desses tratamentos?",acceptedAnswer:{"@type":"Answer",text:"Pessoas com dor, altera\xE7\xF5es de sensibilidade, tontura, dist\xFArbios posturais, les\xF5es traum\xE1ticas ou esportivas, entre outras."}}]}},n=t[a]||t.es,e=document.createElement("script");e.type="application/ld+json",e.textContent=JSON.stringify(n),document.head.appendChild(e)}})();
